import { Order, Effect } from './order';
import { TRANSITIONS } from './transitions';

export function applyEvent(order: Order, event: string, now: Date): Order {
  const transition = TRANSITIONS.find(t => t.from === order.state && t.event === event);
  if (!transition) {
    throw new Error(`Invalid event ${event} for state ${order.state}`);
  }

  if (transition.guard && transition.guard(order, event, now)) {
    throw new Error(transition.guard(order, event, now));
  }

  const updatedOrder = { ...order, state: transition.to, history: [...order.history, { event, timestamp: now }] };

  if (transition.update) {
    Object.assign(updatedOrder, transition.update(updatedOrder, now));
  }

